// Generated by `just generate` from `src/plugins/claudetto/slices/setup/domain/prereqs.ts`. Edit the source and run `just generate`.
// The prerequisites of the sandbox of Claude Code, for each platform, from https://code.claude.com/docs/en/sandboxing:
// "The sandbox runs on macOS, Linux, and WSL2. On native Windows, Claude Code runs commands unsandboxed."
// "macOS: sandboxing uses the built-in Seatbelt framework", so macOS needs no program.
// "Linux and WSL2: the sandbox relies on `bubblewrap` and `socat`."
// The page gives `sudo apt-get install bubblewrap socat` (Ubuntu/Debian) and `sudo dnf install bubblewrap socat` (Fedora).
// The lines for `pacman`, `zypper`, `apk`, and `brew` use the same package names, which these package managers have.
// Claude Code 2.1.301 refuses WSL1 with "Sandboxing requires WSL2. WSL1 is not supported."
// The hard stop sets `failIfUnavailable`, so a missing program stops Claude Code at startup in the checkout.
// This file runs no program: the adapter gives the platform, the kernel release, and a test for a program on `PATH`.

/** The platform of the host: `process.platform` and the kernel release of `os.release()`. */
export type Host = { platform: string; release: string };

/** A program that the sandbox needs, and the package that holds it. */
type Tool = { program: string; pkg: string };

/** The programs that the sandbox needs on Linux and WSL2. */
const LINUX_TOOLS: readonly Tool[] = [
  { program: "bwrap", pkg: "bubblewrap" },
  { program: "socat", pkg: "socat" },
];

/** Each package manager, in the order of the check, and its install command without the packages. */
const MANAGERS: readonly { program: string; install: string }[] = [
  { program: "apt-get", install: "sudo apt-get install" },
  { program: "dnf", install: "sudo dnf install" },
  { program: "pacman", install: "sudo pacman -S --needed" },
  { program: "zypper", install: "sudo zypper install" },
  { program: "apk", install: "sudo apk add" },
  { program: "brew", install: "brew install" },
];

/** Why the sandbox cannot run on the host. */
export type Unsupported = "windows" | "wsl1" | "other";

/** The state of the prerequisites of the sandbox on the host. */
export type ToolsCase =
  | { kind: "ready" }
  | { kind: "missing"; programs: string[]; install: string | undefined }
  | { kind: "unsupported"; why: Unsupported };

/** True when the kernel release is of WSL, such as `5.15.153.1-microsoft-standard-WSL2` or `4.4.0-19041-Microsoft`. */
const isWsl = (release: string): boolean => /microsoft/i.test(release);

/** True when the kernel release of WSL is of WSL2. A WSL1 release ends in `-Microsoft`. */
const isWsl2 = (release: string): boolean =>
  /wsl2|microsoft-standard/i.test(release);

/**
 * The state of the prerequisites of the sandbox on `host`.
 * `has` tells if a program is on `PATH`.
 * For a missing program, `install` is the command of the first package manager that `has` finds, or `undefined`.
 */
export const sandboxToolsOf = (
  host: Host,
  has: (program: string) => boolean,
): ToolsCase => {
  if (host.platform === "darwin") return { kind: "ready" };
  if (host.platform === "win32") return { kind: "unsupported", why: "windows" };
  if (host.platform !== "linux") return { kind: "unsupported", why: "other" };
  if (isWsl(host.release) && !isWsl2(host.release))
    return { kind: "unsupported", why: "wsl1" };
  const missing = LINUX_TOOLS.filter((t) => !has(t.program));
  if (!missing.length) return { kind: "ready" };
  const manager = MANAGERS.find((m) => has(m.program));
  const pkgs = missing.map((t) => t.pkg).join(" ");
  return {
    kind: "missing",
    programs: missing.map((t) => t.program),
    install: manager && `${manager.install} ${pkgs}`,
  };
};
